def close(self) -> None:
    """Terminate the child process and stop the reader thread."""
    if getattr(self, "_closed", False):
        return
    self._closed = True
    self._alive = False
    # Let the reader thread notice _alive=False and stop touching the fd
    # before we close it, so its file descriptor number cannot be reused
    # by another instance while the thread still holds it.
    reader = getattr(self, "_reader", None)
    if reader is not None and reader is not threading.current_thread():
